        this.isDirty = true;
        return ColonyState.ACTIVE;
    }
    if (!this.packageManager.getImportantColonyPlayers().isEmpty() || this.forceLoadTimer > 0) {
        this.isDirty = true;
        return ColonyState.UNLOADED;
    }
    return ColonyState.INACTIVE;
}

